/// <summary>
/// MPJ_28152_CSD_Fulfilment 3.6.2.1 Calculate Qty not reserved
/// </summary>
class METQtyNotReservedCalculateService extends SysOperationServiceBase
{
}

Method.Source:
/// <summary>
/// run method called from controller class
/// </summary>
/// <param name = "_contract"><c>METQtyNotReservedCalculateContract</c> contract class with selected sales line recordSortedList object initialized</param>
void run(METQtyNotReservedCalculateContract _contract)
{
    this.updateSalesLines(_contract.parmSelectedSalesLine()); 
}

    /// <summary>
    /// update salesLine method
    /// </summary>
    /// <param name = "_selectedSalesLine"><c>RecordSortedList</c> of selected sales lines</param>
    void updateSalesLines(RecordSortedList _selectedSalesLine)
    {
        boolean         moreRecords;
        SalesLine       salesLine;
        METSalesLine    metSalesLine;

        moreRecords = _selectedSalesLine.first(salesLine);

        // Loop through selected salesLine
        while (moreRecords)
        {
            ttsbegin;
            metSalesLine = METSalesLine::find(salesLine.RecId, true);

            if (metSalesLine)
            {
                // Assumption qty not reserved is showed in inventory unit
                // Qty not reserved = Deliver remainder – Quantity reserved
                metSalesLine.QtyNotReserved = salesLine.RemainInventPhysical - salesLine.reservedPhysical();
                metSalesLine.doUpdate();
            }
            ttscommit;

            // select the next sales order from the soList
            moreRecords = _selectedSalesLine.next(salesLine);
        
        }
    }
